async (page) => {
  const base = 'http://localhost:3000';
  await page.context().addCookies([
    { name: 'cookieconsent_status', value: 'dismiss', domain: 'localhost', path: '/' },
    { name: 'language', value: 'en', domain: 'localhost', path: '/' },
  ]);
  const email = `explore-${Date.now()}@example.test`;
  const reg = await page.request.post(`${base}/api/Users`, { data: { email, password: 'Passw0rd!x', passwordRepeat: 'Passw0rd!x' } });
  const regBody = await reg.text();
  const login = await page.request.post(`${base}/rest/user/login`, { data: { email, password: 'Passw0rd!x' } });
  const auth = (await login.json()).authentication;
  await page.goto(`${base}/#/search`);
  await page.evaluate((a) => { localStorage.setItem('token', a.token); sessionStorage.setItem('bid', String(a.bid)); document.cookie = `token=${a.token}; path=/`; }, auth);
  await page.goto(`${base}/#/search`);
  await page.waitForTimeout(1500);
  return { reg: reg.status(), regBody: regBody.slice(0, 300), loginStatus: login.status(), bid: auth.bid, snap: await page.locator('body').ariaSnapshot() };
}

