await (async (page) => {
  const base = 'http://localhost:3000';
  const token = await page.evaluate(() => localStorage.getItem('token'));
  const h = { Authorization: `Bearer ${token}` };
  const addr = await page.request.post(`${base}/api/Addresss`, { headers: h, data: { fullName: 'Test Customer', mobileNum: 501234567, zipCode: '01001', streetAddress: '1 Khreshchatyk Street', city: 'Kyiv', state: 'Kyiv', country: 'Ukraine' } });
  const card = await page.request.post(`${base}/api/Cards`, { headers: h, data: { fullName: 'Test Customer', cardNum: 4111111111111111, expMonth: 12, expYear: 2090 } });
  const addrBody = await addr.json();
  const cardBody = await card.json();
  await page.goto(`${base}/#/basket`);
  await page.waitForTimeout(1200);
  await page.getByRole('button', { name: 'Checkout' }).click();
  await page.waitForTimeout(1500);
  return { addrStatus: addr.status(), addrId: addrBody.data?.id, cardStatus: card.status(), cardId: cardBody.data?.id, url: page.url(), snap: await page.locator('body').ariaSnapshot() };
})(page);
