async (page) => {
  await page.goto('http://localhost:3000/#/search');
  await page.reload();
  await page.waitForTimeout(800);
  await page.locator('article').filter({ hasText: 'Apple Juice (1000ml)' }).getByRole('button', { name: 'Add to Basket' }).click();
  await page.waitForTimeout(500);
  const snack = await page.evaluate(() => {
    const hit = [...document.querySelectorAll('*')].find(el => el.children.length === 0 && el.textContent.includes('Placed Apple Juice'));
    if (!hit) return 'NO MATCH';
    const chain = []; let el = hit;
    for (let i = 0; i < 6 && el; i++) { chain.push(el.tagName.toLowerCase() + (el.className && typeof el.className === 'string' ? '.' + el.className.split(' ').slice(0,2).join('.') : '')); el = el.parentElement; }
    return { text: hit.textContent, chain };
  });
  return snack;
}

