/** A customer created through the API. It holds the session data that the browser needs. */
export interface Customer {
  id: number;
  email: string;
  password: string;
  token: string;
  bid: number;
}

/** A customer with the saved address and card of test-cases/README.md. */
export interface CustomerWithSavedCard extends Customer {
  cardId: number;
}

/** Body of POST /api/Addresss. */
export interface SavedAddress {
  fullName: string;
  mobileNum: number;
  zipCode: string;
  streetAddress: string;
  city: string;
  state: string;
  country: string;
}

/** Body of POST /api/Cards. */
export interface SavedCard {
  fullName: string;
  cardNum: number;
  expMonth: number;
  expYear: number;
}

/** The shop wraps most answers in `{ status, data }`. */
export interface ApiEnvelope<T> {
  status: string;
  data: T;
}

/** Answer of POST /rest/user/login. */
export interface LoginResponse {
  authentication: {
    token: string;
    bid: number;
    umail: string;
  };
}

