import { encode } from 'z85';

/** Month codes of a coupon text, as the shop reads them. */
const MONTH_CODES = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;
const YEAR_MODULO = 100;
const TWO_DIGITS = 2;

/**
 * Builds coupon codes for the month of the machine that runs the app.
 * A coupon code is the Z85 encoding of `<MMM><YY>-<NN>` (test-cases/README.md).
 */
export class CouponHelper {
  static currentMonth(discountPercent: number): string {
    return buildCouponCode(new Date(), discountPercent);
  }

  static previousMonth(discountPercent: number): string {
    const now = new Date();
    return buildCouponCode(new Date(now.getFullYear(), now.getMonth() - 1, 1), discountPercent);
  }
}

function buildCouponCode(date: Date, discountPercent: number): string {
  const month = MONTH_CODES[date.getMonth()];
  const year = String(date.getFullYear() % YEAR_MODULO).padStart(TWO_DIGITS, '0');
  const percent = String(discountPercent).padStart(TWO_DIGITS, '0');
  const encoded = encode(`${month}${year}-${percent}`);
  if (encoded === null) {
    throw new Error(`Coupon text ${month}${year}-${percent} has a length that Z85 cannot encode`);
  }
  return encoded;
}

