import type { APIRequestContext } from '@playwright/test';

export type HttpMethod = 'GET' | 'POST' | 'PUT';

export interface ApiCallOptions {
  /** Sent as `Authorization: Bearer <token>`. The server does not read the token from a cookie. */
  token?: string;
  data?: unknown;
}

/**
 * Base of the API clients for test-data setup. A failed call throws with the server's answer,
 * so a broken setup stops the test at the step that failed.
 */
export class ApiClient {
  constructor(private readonly request: APIRequestContext) {}

  protected async call<T>(method: HttpMethod, path: string, options: ApiCallOptions = {}): Promise<T> {
    const response = await this.request.fetch(path, {
      method,
      data: options.data,
      headers: options.token ? { Authorization: `Bearer ${options.token}` } : undefined,
    });
    if (!response.ok()) {
      throw new Error(`${method} ${path} failed with ${response.status()}: ${await response.text()}`);
    }
    return (await response.json()) as T;
  }
}

