import { ApiClient } from '@/core/api/api-client';
import { API_ROUTES } from '@/utils/constants/routes';
import type { ApiEnvelope } from '@/utils/types/shop-types';

interface ProductSummary {
  id: number;
  name: string;
}

export class ProductApi extends ApiClient {
  /** Finds the product id by its exact name, through the product search of the shop. */
  async findProductId(name: string): Promise<number> {
    const answer = await this.call<ApiEnvelope<ProductSummary[]>>(
      'GET',
      `${API_ROUTES.productsSearch}?q=${encodeURIComponent(name)}`,
    );
    const product = answer.data.find((item) => item.name === name);
    if (!product) {
      throw new Error(`Product "${name}" is not in the catalog search`);
    }
    return product.id;
  }
}

