import type { Page } from '@playwright/test';
import { expectHidden, expectVisible } from '@/utils/assertions/ui-assertions';

/** The account menu of the top bar and its sub-menu `Orders & Payment`. */
export class AccountMenuComponent {
  constructor(private readonly page: Page) {}

  async open(): Promise<void> {
    await this.page.getByRole('button', { name: 'Show/hide account menu' }).click();
  }

  async close(): Promise<void> {
    await this.page.keyboard.press('Escape');
  }

  async openOrdersAndPayment(): Promise<void> {
    await this.page.getByRole('menuitem', { name: 'Show Orders and Payment Menu' }).click();
  }

  async clickOrderHistory(): Promise<void> {
    await this.page.getByRole('menuitem', { name: 'Go to order history page' }).click();
  }

  async clickDigitalWallet(): Promise<void> {
    await this.page.getByRole('menuitem', { name: 'Go to wallet page' }).click();
  }

  async shouldSeeLoginItem(): Promise<void> {
    await expectVisible(this.page.getByRole('menuitem', { name: 'Login' }), 'Account menu shows the item Login');
  }

  async shouldSeeLogoutItem(): Promise<void> {
    await expectVisible(this.page.getByRole('menuitem', { name: 'Logout' }), 'Account menu shows the item Logout');
  }

  async shouldSeeEmail(email: string): Promise<void> {
    await expectVisible(
      this.page.getByRole('menuitem', { name: 'Go to user profile' }).getByText(email, { exact: true }),
      'Account menu shows the email of the account',
    );
  }

  async shouldNotSeeEmail(email: string): Promise<void> {
    await expectHidden(
      this.page.getByRole('menuitem', { name: 'Go to user profile' }).getByText(email, { exact: true }),
      'Account menu does not show the email',
    );
  }

  async shouldNotBeOpen(): Promise<void> {
    await expectHidden(this.page.getByRole('menuitem', { name: 'Login' }), 'Account menu is closed');
  }
}

