import { AccountMenuComponent } from '@/page-objects/components/account-menu.component';
import { NavBarComponent } from '@/page-objects/components/navbar.component';
import { SnackBarComponent } from '@/page-objects/components/snack-bar.component';

/**
 * Base of every page. It holds the top bar, the account menu and the messages, which every page shows.
 * Specs reach them only through the page, never through the components.
 */
export abstract class BasePage {
  protected readonly navbar: NavBarComponent;
  protected readonly accountMenu: AccountMenuComponent;
  protected readonly snackBar: SnackBarComponent;

  constructor(protected readonly page: Page) {
    this.navbar = new NavBarComponent(page);
    this.accountMenu = new AccountMenuComponent(page);
    this.snackBar = new SnackBarComponent(page);
  }

  async openBasketFromTopBar(): Promise<void> {
    await this.navbar.openBasket();
  }

  async shouldSeeBasketCounter(count: number): Promise<void> {
    await this.navbar.shouldSeeBasketCounter(count);
  }

  async shouldSeeMessage(message: string): Promise<void> {
    await this.snackBar.shouldSeeMessage(message);
  }

  async openAccountMenu(): Promise<void> {
    await this.accountMenu.open();
  }

  async closeAccountMenu(): Promise<void> {
    await this.accountMenu.close();
  }

  async openOrderHistoryFromMenu(): Promise<void> {
    await this.accountMenu.open();
    await this.accountMenu.openOrdersAndPayment();
    await this.accountMenu.clickOrderHistory();
  }

  async openWalletFromMenu(): Promise<void> {
    await this.accountMenu.open();
    await this.accountMenu.openOrdersAndPayment();
    await this.accountMenu.clickDigitalWallet();
  }

  async shouldSeeLoginItemInAccountMenu(): Promise<void> {
    await this.accountMenu.shouldSeeLoginItem();
  }

  async shouldSeeEmailInAccountMenu(email: string): Promise<void> {
    await this.accountMenu.shouldSeeEmail(email);
  }

  async shouldNotSeeEmailInAccountMenu(email: string): Promise<void> {
    await this.accountMenu.shouldNotSeeEmail(email);
  }

  async shouldSeeLogoutItemInAccountMenu(): Promise<void> {
    await this.accountMenu.shouldSeeLogoutItem();
  }
}

