    const card = this.productCard(name);
    await expectVisible(card.getByText(name, { exact: true }), `Product "${name}" is listed`);
    await expectVisible(card.getByText(price, { exact: true }), `Price of "${name}" is ${price}`);
    await expectVisible(card.getByRole('button', { name: ADD_TO_BASKET }), `"${name}" has the button ${ADD_TO_BASKET}`);
