import type { Locator } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { APP_ROUTES } from '@/utils/constants/routes';
import { expectCount, expectDisabled, expectEnabled, expectHidden, expectVisible } from '@/utils/assertions/ui-assertions';

const BASKET_TITLE = 'Your Basket';
const CHECKOUT = 'Checkout';

/** The basket `/#/basket`. Each product is one row of the table. */
export class BasketPage extends BasePage {
  async open(): Promise<void> {
    await this.page.goto(APP_ROUTES.basket);
    await this.shouldSeePage();
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.page.getByRole('heading', { name: new RegExp(`^${BASKET_TITLE}`) }), 'Basket page is shown');
  }

  async shouldSeeRow(name: string, quantity: number, price: string): Promise<void> {
    const row = this.row(name);
    await expectVisible(row, `Basket has a row for "${name}"`);
    await expectVisible(row.getByText(String(quantity), { exact: true }), `"${name}" has quantity ${quantity}`);
    await expectVisible(row.getByText(price, { exact: true }), `"${name}" has price ${price}`);
  }

  async shouldNotSeeRow(name: string): Promise<void> {
    await expectHidden(this.row(name), `Basket has no row for "${name}"`);
  }

  async shouldSeeNoProducts(): Promise<void> {
    await expectCount(this.page.getByRole('row').filter({ has: this.page.getByRole('img') }), 0, 'Basket has no products');
  }

  async clickPlusInRow(name: string): Promise<void> {
    await this.row(name).locator('button:has(svg[data-icon="plus-square"])').click();
  }

  async clickMinusInRow(name: string): Promise<void> {
    await this.row(name).locator('button:has(svg[data-icon="minus-square"])').click();
  }

  async clickTrashInRow(name: string): Promise<void> {
    await this.row(name).locator('button:has(svg[data-icon="trash-alt"])').click();
  }

  async shouldSeeTotalPrice(total: string): Promise<void> {
    await expectVisible(this.page.getByText(`Total Price: ${total}`, { exact: true }), `Basket total is ${total}`);
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton().click();
  }

  async shouldSeeCheckoutEnabled(): Promise<void> {
    await expectEnabled(this.checkoutButton(), 'Checkout button is enabled');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton(), 'Checkout button is disabled');
  }

  private row(name: string): Locator {
    return this.page.getByRole('row').filter({ has: this.page.getByRole('img', { name, exact: true }) });
  }

  private checkoutButton(): Locator {
    return this.page.getByRole('button', { name: CHECKOUT, exact: true });
  }
}

