    await expectVisible(this.page.getByRole('heading', { name: LOGIN_TITLE }), 'Login page title is shown');
    await expectVisible(this.page.getByRole('textbox', { name: EMAIL_FIELD }), 'Email field is shown');
    await expectVisible(this.page.getByRole('textbox', { name: PASSWORD_FIELD }), 'Password field is shown');
    await expectVisible(this.loginButton(), 'Log in button is shown');
  }

  async fillEmail(email: string): Promise<void> {
    await this.page.getByRole('textbox', { name: EMAIL_FIELD }).fill(email);
  }

  async fillPassword(password: string): Promise<void> {
    await this.page.getByRole('textbox', { name: PASSWORD_FIELD }).fill(password);
  }

  async clickLogIn(): Promise<void> {
    await this.loginButton().click();
  }

  async login(email: string, password: string): Promise<void> {
    await this.fillEmail(email);
    await this.fillPassword(password);
    await this.clickLogIn();
  }

  async shouldSeeInvalidCredentialsError(): Promise<void> {
    await this.snackBar.shouldSeeMessage(INVALID_LOGIN_MESSAGE);
  }

  /**
   * Starts a logged-in session without the login form: the token and the basket id go into the browser
   * before the app loads (auth-and-sessions.md). Do not use it when the login form is under test.
   */
  async authenticate(customer: Customer): Promise<void> {
    await this.page.context().addCookies([{ name: APP_COOKIE.token.name, value: customer.token, url: this.baseURL }]);
    await this.page.addInitScript(
      ({ token, bid }) => {
        localStorage.setItem('token', token);
        sessionStorage.setItem('bid', String(bid));
      },
      { token: customer.token, bid: customer.bid },
    );
    await this.page.goto(APP_ROUTES.search);
  }

  private loginButton() {
    return this.page.locator('button', { hasText: LOGIN_BUTTON_TEXT });
  }
}

import type { Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { APP_ROUTES } from '@/utils/constants/routes';
import { expectVisible } from '@/utils/assertions/ui-assertions';

const PRODUCT_LIST_TITLE = 'All Products';
const ADD_TO_BASKET = 'Add to Basket';

/** The product list `/#/search`. */
export class SearchPage extends BasePage {
  async open(): Promise<void> {
    await this.page.goto(APP_ROUTES.search);
    await this.shouldSeePage();
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.page.getByText(PRODUCT_LIST_TITLE, { exact: true }), 'Product list is shown');
  }

  async shouldSeeProduct(name: string, price: string): Promise<void> {
    const card = this.productCard(name);
    await expectVisible(card.getByText(name, { exact: true }), `Product "${name}" is listed`);
    await expectVisible(card.getByText(price, { exact: true }), `Price of "${name}" is ${price}`);
    await expectVisible(card.getByRole('button', { name: ADD_TO_BASKET }), `"${name}" has the button ${ADD_TO_BASKET}`);
  }

  async addProductToBasket(name: string): Promise<void> {
    await this.productCard(name).getByRole('button', { name: ADD_TO_BASKET }).click();
  }

  private productCard(name: string) {
    return this.page.locator('article').filter({ has: this.page.getByRole('img', { name, exact: true }) });
  }
}

