import { BasePage } from '@/page-objects/base-page';
import { expectVisible } from '@/utils/assertions/ui-assertions';
import type { SavedAddress } from '@/utils/types/shop-types';

export interface TotalLine {
  label: string;
  value: string;
}

/** Checkout step `Order Summary`, before the order is placed. */
export class OrderSummaryPage extends BasePage {
  async shouldSeePage(): Promise<void> {
    await expectVisible(this.page.getByText('Order Summary', { exact: true }), 'Order summary is shown');
  }

  async shouldSeeAddress(address: SavedAddress): Promise<void> {
    await expectVisible(
      this.page.getByText(address.streetAddress, { exact: false }),
      `Order summary shows the address ${address.streetAddress}`,
    );
  }

  async shouldSeeCard(maskedNumber: string): Promise<void> {
    await expectVisible(this.page.getByText(maskedNumber, { exact: false }), `Order summary shows the card ${maskedNumber}`);
  }

  async shouldSeePaymentMethod(method: string): Promise<void> {
    await expectVisible(this.page.getByText(method, { exact: false }), `Order summary shows the payment ${method}`);
  }

  async shouldSeeTotals(lines: TotalLine[]): Promise<void> {
    for (const line of lines) {
      await expectVisible(
        this.page.getByRole('row', { name: `${line.label} ${line.value}`, exact: true }),
        `Order summary: ${line.label} is ${line.value}`,
      );
