import { BasePage } from '@/page-objects/base-page';
import { expectVisible } from '@/utils/assertions/ui-assertions';
import { ORDER_THANK_YOU_MESSAGE } from '@/utils/constants/test-data';
import type { TotalLine } from '@/page-objects/order-summary-page';

/** The confirmation page `/#/order-completion/<order ID>`. */
export class OrderCompletionPage extends BasePage {
  async shouldSeePage(): Promise<void> {
    await expectVisible(
      this.page.getByRole('heading', { name: ORDER_THANK_YOU_MESSAGE }),
      'Order confirmation page is shown',
    );
  }

  /** The order ID is the last part of the URL. */
  readOrderId(): string {
    const orderId = new URL(this.page.url()).hash.split('/').pop();
    if (!orderId) {
      throw new Error(`No order ID in ${this.page.url()}`);
    }
    return orderId;
  }

  async shouldSeeProductLine(name: string, quantity: number, price: string): Promise<void> {
    const row = this.page.getByRole('row').filter({ hasText: name }).filter({ hasText: price });
    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `"${name}" has quantity ${quantity}`);
  }

  /** The totals are one nested table: labels in one cell, values in the next one, in the same order. */
  async shouldSeeTotals(lines: TotalLine[]): Promise<void> {
    const labels = lines.map((line) => line.label).join(' ');
    const values = lines.map((line) => line.value).join(' ');
    await expectVisible(this.page.getByRole('cell', { name: labels, exact: true }), `Totals labels: ${labels}`);
    await expectVisible(this.page.getByRole('cell', { name: values, exact: true }), `Totals values: ${values}`);
  }
}

