};

function requireBaseURL(baseURL: string | undefined): string {
  if (!baseURL) {
    throw new Error('baseURL is not set in playwright.config.ts');
  }
  return baseURL;
}

/** The banner cookies of juice-shop-app.md. They must exist before the first page load. */
function bannerCookies(baseURL: string | undefined): Array<{ name: string; value: string; domain: string; path: string }> {
  const { hostname } = new URL(requireBaseURL(baseURL));
  return [APP_COOKIE.cookieConsent, APP_COOKIE.language].map((cookie) => ({
