import { test } from '@/fixtures/pages.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';

const WRONG_PASSWORD_SUFFIX = 'x';

test('Login with a valid and an invalid password', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.auth],
  annotation: { type: 'test-case', description: 'TC-01' },
}, async ({ api, loginPage, searchPage }) => {
  const customer = await test.step('Precondition: create a customer account', () => api.customers.createCustomer());
  const wrongPassword = `${customer.password}${WRONG_PASSWORD_SUFFIX}`;

  await test.step('1. Open the login page', async () => {
    await loginPage.open();
  });

  await test.step('2. Log in with the wrong password', async () => {
    await loginPage.login(customer.email, wrongPassword);
    await loginPage.shouldSeeInvalidCredentialsError();
    await loginPage.shouldSeePage();
  });

  await test.step('3. Open the account menu', async () => {
    await loginPage.openAccountMenu();
    await loginPage.shouldSeeLoginItemInAccountMenu();
    await loginPage.shouldNotSeeEmailInAccountMenu(customer.email);
  });

  await test.step('4. Log in with the correct password', async () => {
    await loginPage.closeAccountMenu();
    await loginPage.login(customer.email, customer.password);
    await searchPage.shouldSeePage();
  });

  await test.step('5. Open the account menu', async () => {
    await searchPage.openAccountMenu();
    await searchPage.shouldSeeEmailInAccountMenu(customer.email);
    await searchPage.shouldSeeLogoutItemInAccountMenu();
  });
});

