import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { AMOUNTS, PRODUCTS } from '@/utils/constants/test-data';

test('Change the quantity and remove a product in the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-03' },
}, async ({ api, customer, loginPage, basketPage }) => {
  const productA = PRODUCTS.raspberry;
  const productB = PRODUCTS.eggfruit;

  await test.step('Precondition: put product A and product B into the basket', async () => {
    await api.baskets.addProduct(customer, await api.products.findProductId(productA.name), 1);
    await api.baskets.addProduct(customer, await api.products.findProductId(productB.name), 1);
  });

  await test.step('Precondition: log in the customer', () => loginPage.authenticate(customer));

  await test.step('1. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeRow(productA.name, 1, productA.price);
    await basketPage.shouldSeeRow(productB.name, 1, productB.price);
    await basketPage.shouldSeeTotalPrice(AMOUNTS.tc03.twoRows);
    await basketPage.shouldSeeBasketCounter(2);
  });

  await test.step('2. Click the plus button in the row of product A', async () => {
    await basketPage.clickPlusInRow(productA.name);
    await basketPage.shouldSeeRow(productA.name, 2, productA.price);
    await basketPage.shouldSeeTotalPrice(AMOUNTS.tc03.afterPlus);
    await basketPage.shouldSeeBasketCounter(3);
  });

  await test.step('3. Click the minus button in the row of product A', async () => {
    await basketPage.clickMinusInRow(productA.name);
    await basketPage.shouldSeeRow(productA.name, 1, productA.price);
    await basketPage.shouldSeeTotalPrice(AMOUNTS.tc03.twoRows);
    await basketPage.shouldSeeBasketCounter(2);
  });

  await test.step('4. Click the minus button in the row of product A again', async () => {
    await basketPage.clickMinusInRow(productA.name);
    await basketPage.shouldSeeRow(productA.name, 1, productA.price);
    await basketPage.shouldSeeTotalPrice(AMOUNTS.tc03.twoRows);
  });

  await test.step('5. Click the trash button in the row of product A', async () => {
    await basketPage.clickTrashInRow(productA.name);
    await basketPage.shouldNotSeeRow(productA.name);
    await basketPage.shouldSeeRow(productB.name, 1, productB.price);
    await basketPage.shouldSeeTotalPrice(AMOUNTS.tc03.afterRemove);
    await basketPage.shouldSeeBasketCounter(1);
  });
});

