import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { AMOUNTS, PRODUCTS, PURCHASE_LIMIT, PURCHASE_LIMIT_MESSAGE } from '@/utils/constants/test-data';

test('Purchase limit for one product', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-04' },
}, async ({ customer, loginPage, searchPage, basketPage }) => {
  const product = PRODUCTS.apple;

  await test.step('Precondition: log in the new customer with an empty basket', () => loginPage.authenticate(customer));

  await test.step('1. Add the product to the basket from the product list', async () => {
    await searchPage.open();
    await searchPage.addProductToBasket(product.name);
    await searchPage.shouldSeeMessage(`Placed ${product.name} into basket.`);
    await searchPage.shouldSeeBasketCounter(1);
  });

  await test.step('2. Click the plus button until the quantity is at the limit', async () => {
    await basketPage.open();
    for (let click = 1; click < PURCHASE_LIMIT; click++) {
      await basketPage.clickPlusInRow(product.name);
    }
    await basketPage.shouldSeeRow(product.name, PURCHASE_LIMIT, product.price);
    await basketPage.shouldSeeTotalPrice(AMOUNTS.tc04.atLimit);
    await basketPage.shouldNotSeeMessage(PURCHASE_LIMIT_MESSAGE);
  });

  await test.step('3. Click the plus button one more time', async () => {
    await basketPage.clickPlusInRow(product.name);
    await basketPage.shouldSeeMessage(PURCHASE_LIMIT_MESSAGE);
  });

  await test.step('4. Read the basket', async () => {
    await basketPage.shouldSeeRow(product.name, PURCHASE_LIMIT, product.price);
    await basketPage.shouldSeeTotalPrice(AMOUNTS.tc04.atLimit);
    await basketPage.shouldSeeBasketCounter(PURCHASE_LIMIT);
  });

  await test.step('5. Click Add to Basket on the product in the product list', async () => {
    await searchPage.open();
    await searchPage.addProductToBasket(product.name);
    await searchPage.shouldSeeMessage(PURCHASE_LIMIT_MESSAGE);
    await searchPage.shouldSeeBasketCounter(PURCHASE_LIMIT);
  });
});

