import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { CouponHelper } from '@/utils/helpers/coupon-helper';
import {
  AMOUNTS,
  CARD_VIEW,
  COUPON_DISCOUNT_MESSAGE,
  COUPON_DISCOUNT_PERCENT,
  DELIVERY_METHODS,
  PRODUCTS,
  SAVED_ADDRESS,
} from '@/utils/constants/test-data';

test('Order with a card, from basket to order history', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.checkout],
  annotation: { type: 'test-case', description: 'TC-07' },
}, async ({ customerWithSavedCard, loginPage, searchPage, basketPage, addressPage, deliveryPage, paymentPage, orderSummaryPage, orderCompletionPage, orderHistoryPage }) => {
  const productA = PRODUCTS.eggfruit;
  const productB = PRODUCTS.carrot;

  await test.step('Precondition: log in the customer with an empty basket', () => loginPage.authenticate(customerWithSavedCard));

  await test.step('1. Add product A two times and product B one time from the product list', async () => {
    await searchPage.open();
    await searchPage.addProductToBasket(productA.name);
    await searchPage.addProductToBasket(productA.name);
    await searchPage.addProductToBasket(productB.name);
    await searchPage.shouldSeeBasketCounter(3);
  });

  await test.step('2. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeRow(productA.name, 2, productA.price);
    await basketPage.shouldSeeRow(productB.name, 1, productB.price);
    await basketPage.shouldSeeTotalPrice(AMOUNTS.tc07.items);
  });

  await test.step('3. Click Checkout, select the saved address and click Continue', async () => {
    await basketPage.clickCheckout();
    await addressPage.selectSavedAddress(SAVED_ADDRESS);
    await addressPage.clickContinue();
    await deliveryPage.shouldSeePage();
  });

  await test.step('4. Select One Day Delivery and click Continue', async () => {
    await deliveryPage.selectDelivery(DELIVERY_METHODS.oneDay.name);
    await deliveryPage.clickContinue();
    await paymentPage.shouldSeePage();
  });

  await test.step('5. Redeem the coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(CouponHelper.currentMonth(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeDiscountMessage(COUPON_DISCOUNT_MESSAGE);
  });

  await test.step('6. Select the saved card and click Continue', async () => {
    await paymentPage.selectSavedCard();
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeAddress(SAVED_ADDRESS);
    await orderSummaryPage.shouldSeeCard(CARD_VIEW.maskedNumber);
    await orderSummaryPage.shouldSeeTotals([
      { label: 'Items', value: AMOUNTS.tc07.items },
      { label: 'Delivery', value: DELIVERY_METHODS.oneDay.price },
      { label: 'Promotion', value: AMOUNTS.tc07.promotion },
      { label: 'Total Price', value: AMOUNTS.tc07.total },
    ]);
  });

  const orderId = await test.step('7. Click Place your order and pay', async () => {
    await orderSummaryPage.clickPlaceOrder();
    await orderCompletionPage.shouldSeePage();
    return orderCompletionPage.readOrderId();
  });

  await test.step('8. Read the order summary on the confirmation page', async () => {
    await orderCompletionPage.shouldSeeProductLine(productA.name, 2, productA.price);
    await orderCompletionPage.shouldSeeProductLine(productB.name, 1, productB.price);
    await orderCompletionPage.shouldSeeTotals([
      { label: 'Items', value: AMOUNTS.tc07.items },
      { label: 'Delivery', value: DELIVERY_METHODS.oneDay.price },
      { label: 'Promotion', value: AMOUNTS.tc07.promotion },
      { label: 'Total Price', value: AMOUNTS.tc07.total },
    ]);
  });

  await test.step('9. Read the basket counter and open the empty basket', async () => {
    await orderCompletionPage.shouldSeeBasketCounter(0);
    await basketPage.open();
    await basketPage.shouldSeeNoProducts();
    await basketPage.shouldSeeCheckoutDisabled();
  });

  await test.step('10. Open the order history', async () => {
