import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import {
  AMOUNTS,
  DELIVERY_METHODS,
  PRODUCTS,
  SAVED_ADDRESS,
  WALLET,
} from '@/utils/constants/test-data';

const PAY_LABEL = `Pay ${AMOUNTS.tc08.total}`;

test('Payment with the wallet', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.wallet],
  annotation: { type: 'test-case', description: 'TC-08' },
}, async ({ api, customerWithSavedCard, loginPage, basketPage, addressPage, deliveryPage, paymentPage, orderSummaryPage, orderCompletionPage, orderHistoryPage, walletPage }) => {
  const product = PRODUCTS.eggfruit;

  await test.step('Precondition: put the product with quantity 1 into the basket', async () => {
    await api.baskets.addProduct(customerWithSavedCard, await api.products.findProductId(product.name), 1);
  });

  await test.step('Precondition: add 5.00 to the wallet with the saved card', async () => {
    await api.wallet.addMoney(customerWithSavedCard, WALLET.firstTopUp, customerWithSavedCard.cardId);
  });

  await test.step('Precondition: log in the customer', () => loginPage.authenticate(customerWithSavedCard));

  await test.step('1. Open the basket, click Checkout, select the saved address and click Continue', async () => {
    await basketPage.open();
    await basketPage.clickCheckout();
    await addressPage.selectSavedAddress(SAVED_ADDRESS);
    await addressPage.clickContinue();
    await deliveryPage.shouldSeePage();
  });

  await test.step('2. Select Standard Delivery and click Continue', async () => {
    await deliveryPage.selectDelivery(DELIVERY_METHODS.standard.name);
    await deliveryPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(WALLET.firstBalance);
    await paymentPage.shouldSeePayWithWalletButton(PAY_LABEL, false);
  });

  await test.step('3. Read the button Pay and check that it is disabled', async () => {
    await paymentPage.shouldSeePayWithWalletButton(PAY_LABEL, false);
  });

  await test.step('4. Open the order history', async () => {
    await paymentPage.openOrderHistoryFromMenu();
    await orderHistoryPage.shouldSeeNoOrders();
  });

  await test.step('5. Open the digital wallet', async () => {
    await orderHistoryPage.openWalletFromMenu();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(WALLET.firstBalance);
  });

  await test.step('Precondition: add 3.99 to the wallet with the saved card', async () => {
    await api.wallet.addMoney(customerWithSavedCard, WALLET.secondTopUp, customerWithSavedCard.cardId);
  });

  await test.step('6. Open the basket, click Checkout, select the saved address, select Standard Delivery and click Continue', async () => {
    await walletPage.open();
    await basketPage.open();
    await basketPage.clickCheckout();
    await addressPage.selectSavedAddress(SAVED_ADDRESS);
    await addressPage.clickContinue();
    await deliveryPage.selectDelivery(DELIVERY_METHODS.standard.name);
    await deliveryPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(WALLET.balanceAfterSecondTopUp);
    await paymentPage.shouldSeePayWithWalletButton(PAY_LABEL, true);
  });

  await test.step('7. Click the button Pay', async () => {
    await paymentPage.clickPayWithWallet(PAY_LABEL);
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeePaymentMethod('Digital Wallet');
    await orderSummaryPage.shouldSeeTotals([{ label: 'Total Price', value: AMOUNTS.tc08.total }]);
  });

  const orderId = await test.step('8. Click Place your order and pay', async () => {
    await orderSummaryPage.clickPlaceOrder();
    await orderCompletionPage.shouldSeePage();
    return orderCompletionPage.readOrderId();
  });

  await test.step('9. Open the digital wallet', async () => {
    await orderCompletionPage.openWalletFromMenu();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(WALLET.balanceAfterOrder);
  });

  await test.step('10. Open the order history', async () => {
    await walletPage.openOrderHistoryFromMenu();
    await orderHistoryPage.shouldSeeOrder(orderId, AMOUNTS.tc08.total);
    await orderHistoryPage.shouldSeeBonusPoints(orderId, WALLET.orderBonusPoints);
  });
});

