    await deliveryPage.shouldSeeDeliveryOption(DELIVERY_METHODS.standard.name, DELIVERY_METHODS.standard.price);
  });

  await test.step('3. Select One Day Delivery and click Continue', async () => {
    await deliveryPage.selectDelivery(DELIVERY_METHODS.oneDay.name);
    await deliveryPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeSavedCard();
    await paymentPage.shouldSeeCouponPanel();
  });

  await test.step('4. Redeem the coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
