/** The order history `/#/order-history`. */
export class OrderHistoryPage extends BasePage {
  async open(): Promise<void> {
    await this.page.goto(APP_ROUTES.orderHistory);
  }

  async shouldSeeNoOrders(): Promise<void> {
    await expectVisible(this.page.getByText(EMPTY_ORDER_HISTORY_MESSAGE, { exact: true }), 'Order history is empty');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.page.getByText(/^Order ID #/), count, `Order history lists ${count} order(s)`);
  }

  async shouldSeeOrder(orderId: string, total: string): Promise<void> {
    const order = this.orderCard(orderId);
    await expectVisible(order, `Order history has the order ${orderId}`);
    await expectVisible(order.getByText(`Total Price ${total}`, { exact: false }), `Order ${orderId} total is ${total}`);
  }

  async shouldSeeBonusPoints(orderId: string, bonusPoints: number): Promise<void> {
    await expectVisible(
      this.orderCard(orderId).getByText(`Bonus ${bonusPoints}`, { exact: false }),
      `Order ${orderId} gives ${bonusPoints} bonus point(s)`,
    );
  }

  async shouldSeeOrderLine(orderId: string, name: string, quantity: number): Promise<void> {
    const row = this.orderCard(orderId).getByRole('row').filter({ hasText: name });
    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `Order ${orderId} has "${name}" x ${quantity}`);
  }

  private orderCard(orderId: string) {
    return this.page.locator('div, mat-card').filter({ hasText: `Order ID #${orderId}` }).last();
  }
}

