async (page) => {
  await page.goto('http://localhost:3000/#/login');
  await page.reload();
  await page.waitForTimeout(800);
  await page.getByRole('textbox', { name: 'Text field for the login email' }).fill('nobody@example.test');
  await page.getByRole('textbox', { name: 'Text field for the login password' }).fill('wrongpass');
  await page.getByRole('button', { name: 'Login', exact: true }).click();
  await page.waitForTimeout(1200);
  return await page.evaluate(() => {
    const hit = [...document.querySelectorAll('*')].filter(el => el.children.length === 0 && /Invalid email/.test(el.textContent));
    return hit.map(el => { const chain = []; let e = el; for (let i = 0; i < 5 && e; i++) { chain.push(e.tagName.toLowerCase() + (typeof e.className === 'string' && e.className ? '.' + e.className.split(' ').slice(0, 2).join('.') : '')); e = e.parentElement; } return { text: el.textContent, chain }; });
