import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { CouponPanelComponent } from '@/page-objects/components/coupon-panel.component';
import { CARD_VIEW } from '@/utils/constants/test-data';
import { expectDisabled, expectEnabled, expectVisible } from '@/utils/assertions/ui-assertions';

const CONTINUE = 'Continue';

/** Checkout step `My Payment Options`: the saved cards, the coupon panel and the wallet payment. */
export class PaymentPage extends BasePage {
  private readonly couponPanel: CouponPanelComponent;

  constructor(page: Page) {
    super(page);
    this.couponPanel = new CouponPanelComponent(page);
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.page.getByRole('heading', { name: 'My Payment Options' }), 'Payment options page is shown');
  }

  async shouldSeeSavedCard(): Promise<void> {
    await expectVisible(
      this.page.getByRole('row').filter({ hasText: CARD_VIEW.maskedNumber }).getByText(CARD_VIEW.expiry),
      `Saved card ${CARD_VIEW.maskedNumber} is listed`,
    );
  }

  async selectSavedCard(): Promise<void> {
    await this.savedCardRow().getByRole('radio').click();
  }

  async clickContinue(): Promise<void> {
    await this.page.locator('button', { hasText: CONTINUE }).click();
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanel.open();
  }

  async shouldSeeCouponPanel(): Promise<void> {
    await this.couponPanel.shouldSeePanelButton();
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponPanel.fillCoupon(code);
    await this.couponPanel.clickRedeem();
  }

  async shouldSeeDiscountMessage(message: string): Promise<void> {
    await this.couponPanel.shouldSeeDiscountMessage(message);
  }

  async shouldNotSeeDiscountMessage(messageStart: string): Promise<void> {
    await this.couponPanel.shouldNotSeeDiscountMessage(messageStart);
  }

  async shouldSeeWalletBalance(balance: string): Promise<void> {
    await expectVisible(
      this.page.getByText(`Wallet Balance ${balance}`, { exact: true }),
      `Wallet balance on the payment page is ${balance}`,
    );
  }

  async shouldSeePayWithWalletButton(label: string, enabled: boolean): Promise<void> {
    const button = this.page.getByRole('button', { name: label, exact: true });
    if (enabled) {
      await expectEnabled(button, `Button "${label}" is enabled`);
    } else {
      await expectDisabled(button, `Button "${label}" is disabled`);
    }
  }

  async clickPayWithWallet(label: string): Promise<void> {
    await this.page.getByRole('button', { name: label, exact: true }).click();
  }

  private savedCardRow(): Locator {
    return this.page.getByRole('row').filter({ hasText: CARD_VIEW.maskedNumber });
  }
}

