6	/**
7	 * Base of every page. It holds the top bar, the account menu and the messages, which every page shows.
8	 * Specs reach them only through the page, never through the components.
9	 */
10	export abstract class BasePage {
11	  protected readonly navbar: NavBarComponent;
12	  protected readonly accountMenu: AccountMenuComponent;
13	  protected readonly snackBar: SnackBarComponent;
14	
15	  constructor(protected readonly page: Page) {
16	    this.navbar = new NavBarComponent(page);
17	    this.accountMenu = new AccountMenuComponent(page);
18	    this.snackBar = new SnackBarComponent(page);
19	  }
20	
21	  async openBasketFromTopBar(): Promise<void> {
22	    await this.navbar.openBasket();
23	  }
24	
25	  async shouldSeeBasketCounter(count: number): Promise<void> {
26	    await this.navbar.shouldSeeBasketCounter(count);
27	  }
28	
29	  async shouldSeeMessage(message: string): Promise<void> {
30	    await this.snackBar.shouldSeeMessage(message);
31	  }
32	
33	  async shouldNotSeeMessage(message: string): Promise<void> {
34	    await this.snackBar.shouldNotSeeMessage(message);
35	  }
36	
37	  async openAccountMenu(): Promise<void> {
38	    await this.accountMenu.open();
39	  }
40	
41	  async closeAccountMenu(): Promise<void> {
42	    await this.accountMenu.close();
43	  }
44	
45	  async openOrderHistoryFromMenu(): Promise<void> {
46	    await this.accountMenu.open();
47	    await this.accountMenu.openOrdersAndPayment();
48	    await this.accountMenu.clickOrderHistory();
49	  }
50	
51	  async openWalletFromMenu(): Promise<void> {
52	    await this.accountMenu.open();
53	    await this.accountMenu.openOrdersAndPayment();
54	    await this.accountMenu.clickDigitalWallet();
55	  }
56	
57	  async shouldSeeLoginItemInAccountMenu(): Promise<void> {
58	    await this.accountMenu.shouldSeeLoginItem();
59	  }
60	
