62	    await this.accountMenu.shouldSeeEmail(email);
63	  }
64	
65	  async shouldNotSeeEmailInAccountMenu(email: string): Promise<void> {
66	    await this.accountMenu.shouldNotSeeEmail(email);
67	  }
68	
69	  async shouldSeeLogoutItemInAccountMenu(): Promise<void> {
70	    await this.accountMenu.shouldSeeLogoutItem();
71	  }
72	}
