1	import { encode } from 'z85';
2	
3	/** Month codes of a coupon text, as the shop reads them. */
4	const MONTH_CODES = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;
5	const YEAR_MODULO = 100;
6	const TWO_DIGITS = 2;
7	
8	/**
9	 * Builds coupon codes for the month of the machine that runs the app.
10	 * A coupon code is the Z85 encoding of `<MMM><YY>-<NN>` (test-cases/README.md).
11	 */
12	export class CouponHelper {
13	  static currentMonth(discountPercent: number): string {
14	    return buildCouponCode(new Date(), discountPercent);
15	  }
16	
17	  static previousMonth(discountPercent: number): string {
18	    const now = new Date();
19	    return buildCouponCode(new Date(now.getFullYear(), now.getMonth() - 1, 1), discountPercent);
20	  }
21	}
22	
23	function buildCouponCode(date: Date, discountPercent: number): string {
24	  const month = MONTH_CODES[date.getMonth()];
25	  const year = String(date.getFullYear() % YEAR_MODULO).padStart(TWO_DIGITS, '0');
26	  const percent = String(discountPercent).padStart(TWO_DIGITS, '0');
27	  const encoded = encode(`${month}${year}-${percent}`);
28	  if (encoded === null) {
29	    throw new Error(`Coupon text ${month}${year}-${percent} has a length that Z85 cannot encode`);
30	  }
31	  return encoded;
32	}
