import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { CouponHelper } from '@/utils/helpers/coupon-helper';
import {
  AMOUNTS,
  COUPON_DISCOUNT_MESSAGE,
  COUPON_DISCOUNT_PERCENT,
  DELIVERY_METHODS,
  INVALID_COUPON_CODE,
  INVALID_COUPON_MESSAGE,
  PRODUCTS,
  SAVED_ADDRESS,
} from '@/utils/constants/test-data';

const DISCOUNT_MESSAGE_START = COUPON_DISCOUNT_MESSAGE.slice(0, COUPON_DISCOUNT_MESSAGE.indexOf(' will'));

test('Invalid coupon and expired coupon', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-06' },
}, async ({ api, customerWithSavedCard, loginPage, basketPage, addressPage, deliveryPage, paymentPage, orderSummaryPage }) => {
  const product = PRODUCTS.eggfruit;
  const quantity = 2;

  await test.step('Precondition: put the product with quantity 2 into the basket', async () => {
    await api.baskets.addProduct(customerWithSavedCard, await api.products.findProductId(product.name), quantity);
  });

  await test.step('Precondition: log in the customer', () => loginPage.authenticate(customerWithSavedCard));

  await test.step('1. Open the basket, click Checkout, select the saved address and click Continue', async () => {
    await basketPage.open();
    await basketPage.clickCheckout();
    await addressPage.selectSavedAddress(SAVED_ADDRESS);
    await addressPage.clickContinue();
    await deliveryPage.shouldSeePage();
  });

  await test.step('2. Select One Day Delivery and click Continue', async () => {
    await deliveryPage.selectDelivery(DELIVERY_METHODS.oneDay.name);
    await deliveryPage.clickContinue();
    await paymentPage.shouldSeePage();
  });

  await test.step('3. Redeem the invalid code', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(INVALID_COUPON_CODE);
    await paymentPage.shouldSeeCouponError(INVALID_COUPON_MESSAGE);
    await paymentPage.shouldNotSeeDiscountMessage(DISCOUNT_MESSAGE_START);
  });

  await test.step('4. Redeem the expired coupon', async () => {
    await paymentPage.redeemCoupon(CouponHelper.previousMonth(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeCouponError(INVALID_COUPON_MESSAGE);
    await paymentPage.shouldNotSeeDiscountMessage(DISCOUNT_MESSAGE_START);
  });

  await test.step('5. Select the saved card and click Continue', async () => {
    await paymentPage.selectSavedCard();
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeTotals([
      { label: 'Items', value: AMOUNTS.tc06.items },
      { label: 'Delivery', value: DELIVERY_METHODS.oneDay.price },
      { label: 'Promotion', value: AMOUNTS.tc06.promotion },
      { label: 'Total Price', value: AMOUNTS.tc06.total },
    ]);
  });
});

