import type { Locator } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { APP_ROUTES } from '@/utils/constants/routes';
import { EMPTY_ORDER_HISTORY_MESSAGE } from '@/utils/constants/test-data';
import { expectCount, expectText, expectVisible } from '@/utils/assertions/ui-assertions';

/** The order history `/#/order-history`. */
export class OrderHistoryPage extends BasePage {
  async open(): Promise<void> {
    await this.page.goto(APP_ROUTES.orderHistory);
  }

  async shouldSeeNoOrders(): Promise<void> {
    await expectVisible(this.page.getByText(EMPTY_ORDER_HISTORY_MESSAGE, { exact: true }), 'Order history is empty');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.page.getByText('Order ID', { exact: true }), count, `Order history lists ${count} order(s)`);
  }

  async shouldSeeOrder(orderId: string, total: string): Promise<void> {
    await expectVisible(this.orderIdValue(orderId), `Order history has the order ${orderId}`);
    await expectText(this.valueOf(orderId, 'Total Price'), total, `Order ${orderId} total is ${total}`);
  }

  async shouldSeeBonusPoints(orderId: string, bonusPoints: number): Promise<void> {
    await expectText(
      this.valueOf(orderId, 'Bonus'),
      String(bonusPoints),
      `Order ${orderId} gives ${bonusPoints} bonus point(s)`,
    );
  }

  async shouldSeeOrderLine(name: string, quantity: number): Promise<void> {
    const row = this.page.getByRole('row').filter({ hasText: name });
    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `Order has "${name}" x ${quantity}`);
  }

  /** The ID is shown as `#<id>` in its own element, next to the label `Order ID`. */
  private orderIdValue(orderId: string): Locator {
    return this.page.getByText(`#${orderId}`, { exact: true });
  }

  /** The value that sits next to a label (`Total Price`, `Bonus`) in the card of the order. */
  private valueOf(orderId: string, label: string): Locator {
    const card = this.orderIdValue(orderId).locator('xpath=../..');
    return card.getByText(label, { exact: true }).locator('xpath=following-sibling::*[1]');
  }
}

